// swift-tools-version: 6.1
import PackageDescription

let package = Package(
    name: "LRU",
    products: [.executable(name: "app", targets: ["app"])],
    targets: [
        .target(name: "LRUCore"),
        .executableTarget(name: "app", dependencies: ["LRUCore"]),
        .testTarget(name: "LRUCoreTests", dependencies: ["LRUCore"]),
    ]
)

/// Interprets the line-oriented LRU command language.
public struct CommandProcessor {
    private var cache: LRUCache<String, String>

    public init(capacity: Int) {
        cache = LRUCache(capacity: capacity)
    }

    /// Parses the capacity header line, returning `nil` if it is invalid.
    public static func parseCapacity(_ line: some StringProtocol) -> Int? {
        guard let value = Int(String(line.filter { !$0.isWhitespace })), value >= 1 else { return nil }
        return value
    }

    /// Executes one command line, returning the output line it produces, if any.
    /// Unrecognized or malformed lines produce no output.
    public mutating func execute(_ line: Substring) -> String? {
        let tokens = line.split(separator: " ", omittingEmptySubsequences: true)
        guard let command = tokens.first else { return nil }
        switch (command, tokens.count) {
        case ("SET", 3):
            cache.set(String(tokens[1]), String(tokens[2]))
            return nil
        case ("GET", 2):
            return cache.get(String(tokens[1])) ?? "NULL"
        case ("DEL", 2):
            return cache.remove(String(tokens[1])) ? "1" : "0"
        case ("SIZE", 1):
            return String(cache.count)
        default:
            return nil
        }
    }
}

/// A fixed-capacity least-recently-used cache.
///
/// Entries live in a contiguous node pool linked into a doubly linked
/// recency list by index, so every operation runs in O(1) expected time
/// without per-entry heap allocations for list nodes.
public struct LRUCache<Key: Hashable, Value> {
    private struct Node {
        var key: Key
        var value: Value
        var prev: Int
        var next: Int
    }

    private static var none: Int { -1 }

    public let capacity: Int
    private var index: [Key: Int] = [:]
    private var nodes: [Node] = []
    private var freeSlots: [Int] = []
    /// Most recently used node.
    private var head = LRUCache.none
    /// Least recently used node.
    private var tail = LRUCache.none

    public init(capacity: Int) {
        precondition(capacity >= 1, "capacity must be at least 1")
        self.capacity = capacity
        let reserved = min(capacity, 1 << 20)
        index.reserveCapacity(reserved)
        nodes.reserveCapacity(reserved)
    }

    public var count: Int { index.count }

    /// Returns the value for `key`, marking it as most recently used.
    public mutating func get(_ key: Key) -> Value? {
        guard let slot = index[key] else { return nil }
        moveToFront(slot)
        return nodes[slot].value
    }

    /// Inserts or overwrites `key`, marking it as most recently used and
    /// evicting the least recently used entry if capacity is exceeded.
    public mutating func set(_ key: Key, _ value: Value) {
        if let slot = index[key] {
            nodes[slot].value = value
            moveToFront(slot)
            return
        }
        if index.count == capacity {
            evictLeastRecentlyUsed()
        }
        let node = Node(key: key, value: value, prev: Self.none, next: Self.none)
        let slot: Int
        if let reused = freeSlots.popLast() {
            nodes[reused] = node
            slot = reused
        } else {
            nodes.append(node)
            slot = nodes.count - 1
        }
        index[key] = slot
        pushFront(slot)
    }

    /// Removes `key`, returning whether it was present.
    @discardableResult
    public mutating func remove(_ key: Key) -> Bool {
        guard let slot = index.removeValue(forKey: key) else { return false }
        unlink(slot)
        freeSlots.append(slot)
        return true
    }

    private mutating func evictLeastRecentlyUsed() {
        let slot = tail
        guard slot != Self.none else { return }
        index.removeValue(forKey: nodes[slot].key)
        unlink(slot)
        freeSlots.append(slot)
    }

    private mutating func moveToFront(_ slot: Int) {
        guard slot != head else { return }
        unlink(slot)
        pushFront(slot)
    }

    private mutating func pushFront(_ slot: Int) {
        nodes[slot].prev = Self.none
        nodes[slot].next = head
        if head != Self.none {
            nodes[head].prev = slot
        } else {
            tail = slot
        }
        head = slot
    }

    private mutating func unlink(_ slot: Int) {
        let prev = nodes[slot].prev
        let next = nodes[slot].next
        if prev != Self.none { nodes[prev].next = next } else { head = next }
        if next != Self.none { nodes[next].prev = prev } else { tail = prev }
        nodes[slot].prev = Self.none
        nodes[slot].next = Self.none
    }
}

import LRUCore

/// Reads commands from standard input and writes their results to standard output.
func run() {
    guard let header = readLine(), let capacity = CommandProcessor.parseCapacity(header) else {
        return
    }

    var processor = CommandProcessor(capacity: capacity)
    let flushThreshold = 1 << 16
    var output = ""
    output.reserveCapacity(flushThreshold + 128)

    while let line = readLine() {
        var command = Substring(line)
        while command.last == "\r" { command.removeLast() }
        guard let result = processor.execute(command) else { continue }
        output += result
        output += "\n"
        if output.utf8.count >= flushThreshold {
            print(output, terminator: "")
            output.removeAll(keepingCapacity: true)
        }
    }
    print(output, terminator: "")
}

run()

import Testing
@testable import LRUCore

@Suite struct LRUCacheTests {
    @Test func evictsLeastRecentlyUsed() {
        var cache = LRUCache<String, String>(capacity: 2)
        cache.set("a", "1")
        cache.set("b", "2")
        #expect(cache.get("a") == "1")
        cache.set("c", "3")
        #expect(cache.get("b") == nil)
        #expect(cache.count == 2)
    }

    @Test func overwriteRefreshesRecency() {
        var cache = LRUCache<String, String>(capacity: 2)
        cache.set("a", "1")
        cache.set("b", "2")
        cache.set("a", "9")
        cache.set("c", "3")
        #expect(cache.get("a") == "9")
        #expect(cache.get("b") == nil)
    }

    @Test func removeReportsPresenceAndReusesSlots() {
        var cache = LRUCache<String, String>(capacity: 3)
        cache.set("x", "1")
        #expect(cache.remove("x"))
        #expect(!cache.remove("x"))
        #expect(cache.count == 0)
        for i in 0..<10 { cache.set("k\(i)", "\(i)") }
        #expect(cache.count == 3)
        #expect(cache.get("k9") == "9")
        #expect(cache.get("k6") == nil)
    }

    @Test func processorFormatsOutput() {
        var p = CommandProcessor(capacity: 1)
        #expect(p.execute("SET a 1") == nil)
        #expect(p.execute("GET a") == "1")
        #expect(p.execute("GET b") == "NULL")
        #expect(p.execute("DEL a") == "1")
        #expect(p.execute("SIZE") == "0")
    }
}
